mapper.sql:
where 1 = 1

  and t.status = #{status}


  and t.priority = #{priority}


  and (
    lower(t.id) like concat('%', lower(#{keyword}), '%')
    or lower(t.title) like concat('%', lower(#{keyword}), '%')
    or lower(t.description) like concat('%', lower(#{keyword}), '%')
  )


  and t.created_at >= #{startDate}


  and t.created_at <= #{endDate}

mapper.select:
select ticket_id, asset_id from biz_ticket_asset_rel where ticket_id in
#{ticketId}
order by ticket_id asc, asset_id asc
